window.docContents[94].resolve({"/Verified-Symbolic-and-Continuous-Computation/#PDEAtlas--Verified-Symbolic-and-Continuous-Computation--Scope___-Trust___-and-Notes":{"contents":"Once an analytic proof has reduced a problem to a supported exact identity,\nderivative, integral, enclosure, or residual bound, we can compute that object\nand return a theorem that the kernel checks. The surrounding analysis, such as\na weak formulation, trace regularity, a Galerkin limit, or an existence\ntheorem, is proved in the usual way.\n\n\n\n\n\n\n\n","context":"PDEAtlas\u0009Verified Symbolic and Continuous Computation","header":"10.10. Scope, Trust, and Notes","id":"/Verified-Symbolic-and-Continuous-Computation/#PDEAtlas--Verified-Symbolic-and-Continuous-Computation--Scope___-Trust___-and-Notes"}});